setInterval(()=>{for(const clock of document.querySelectorAll('.profile-idle-clock'))clock.textContent=Math.max(0,Math.ceil((Number(clock.dataset.expires)-Date.now()-remoteClock)/1000))+'s';},1000);
function profileShowcase(f,now,force=false){if(!force&&(!f.profileAttract||now-(f.lastProfileActivityAt||now)<20000))return null;const start=force?(f.profileShowcaseStartedAt||f.profileAttract?.startedAt||now):f.profileAttract.startedAt;const elapsed=Math.max(0,now-start),minute=Math.floor(elapsed/60000),second=Math.floor(elapsed%60000/1000),order=[[0,1,2],[1,2,0],[2,0,1]][minute%3],characters=[{id:'showcase-lion',name:'🦁 GOLD LION'},{id:'showcase-dragon',name:'🐉 FROST DRAGON'},{id:'showcase-diamond',name:'💎 DIAMOND STAR'}];return{members:order.map((index,rank)=>({...characters[index],showcase:true,avatar:'',points:400+minute*1000+(3-rank)*200+second*8,coins:0,likes:0,comments:0,lastActivityAt:now}))};}
