setInterval(()=>{if(experience!=='portraits')return;const f=game.s.fun,r=f.profileRound,view=profilePodiumView(f,Date.now()+remoteClock);if(view.members.some(p=>p.showcase)&&!(r?.phase==='finished'&&r.winner))renderProfilePodium($('#funCards'),view.members,{...r,showcase:view.showcase,liveChart:true});},1000);

function profileActivityChart(f){const r=f.profileRound;return [...(r?.chartMembers||r?.members||[])].filter(m=>m.points>=0&&f.people.some(p=>p.id===m.id&&p.lastActivityAt)).sort((a,b)=>b.points-a.points||(b.id===r?.chartThroneId?1:0)-(a.id===r?.chartThroneId?1:0)||a.lastActivityAt-b.lastActivityAt);}
