function renderProfileHostControls(f){const people=f.people||[],members=game.profilePodiumMembers(Date.now()+remoteClock),pins=f.podiumOverrides||{},signature=JSON.stringify(people.map(p=>[p.id,p.name]));for(let seat=1;seat<=3;seat++){const select=$('#profileSeat'+seat),old=select.value;if(select.dataset.people!==signature){select.replaceChildren();const auto=el('option','','خودکار');auto.value='';select.append(auto);for(const p of people){const option=el('option','',p.name);option.value=p.id;select.append(option);}select.dataset.people=signature;if(select.dataset.dirty==='1')select.value=old;}if(select.dataset.dirty!=='1')select.value=pins[seat]||members[seat-1]?.id||'';$('#removeProfileSeat'+seat).disabled=!members[seat-1];}$('#profileHostStatus').textContent=Object.values(pins).some(id=>people.some(p=>p.id===id))?'چیدمان دستی؛ برای رتبه‌بندی زنده «خودکار» را بزنید.':'چیدمان خودکار بر اساس فعالیت';const restore=$('#profileRestore'),hidden=f.hiddenProfiles||[],key=JSON.stringify(hidden.map(p=>[p.id,p.name]));if(restore.dataset.people!==key){const old=restore.value;restore.replaceChildren();for(const p of hidden){const option=el('option','',p.name);option.value=p.id;restore.append(option);}restore.dataset.people=key;if(hidden.some(p=>p.id===old))restore.value=old;}$('#profileRestoreRow').hidden=!hidden.length;}
for(let seat=1;seat<=3;seat++){$('#profileSeat'+seat).onchange=e=>e.target.dataset.dirty='1';$('#assignProfileSeat'+seat).onclick=()=>{const select=$('#profileSeat'+seat),userId=select.value;select.dataset.dirty='';uiCommand('profileHost',{action:'assign',seat,userId},()=>game.profileHost('assign',seat,userId));};$('#removeProfileSeat'+seat).onclick=()=>{const person=game.profilePodiumMembers(Date.now()+remoteClock)[seat-1];if(person)uiCommand('profileHost',{action:'remove',userId:person.id},()=>game.profileHost('remove',seat,person.id));};}
