function renderDashboard(){if(experience==='football'){const list=activeSupporters(game.s,Date.now()+remoteClock),signature=JSON.stringify(list);if(signature===supportersSignature)return;supportersSignature=signature;const root=$('#supporterDashboard');root.replaceChildren();for(let i=0;i<4;i++){const person=list[i],kind=person?.kind==='gift'?'gift':'like',tile=el('div','supporter-stat live-supporter '+kind+(person?.featured?' featured':''));tile.dataset.rank=i+1;if(person){tile.dataset.supporter=person.id;tile.append(avatar(person));const text=el('div');text.append(el('small','',person.featured?(kind==='gift'?'FEATURED GIFTER':'FEATURED LIKER'):(kind==='gift'?'GIFTER':'LIKER')),el('strong','',person.name));tile.append(text,el('b','',fa(kind==='gift'?person.coins:person.likes)));}else{tile.classList.add('empty-supporter');tile.append(el('small','','SUPPORTER '+(i+1)));}root.append(tile);}return;}const people=game.s.supporters||[],gifters=people.filter(x=>x.coins>0).sort((a,b)=>b.coins-a.coins),likers=people.filter(x=>x.likes>0).sort((a,b)=>b.likes-a.likes),lastGift=people.filter(x=>x.lastType==='gift').sort((a,b)=>b.lastAt-a.lastAt)[0],lastLike=people.filter(x=>x.lastType==='like').sort((a,b)=>b.lastAt-a.lastAt)[0],cells=[['گیفتر برتر',gifters[0],'coins'],['لایکر برتر',likers[0],'likes'],['آخرین گیفتر',lastGift,'coins'],['آخرین لایکر',lastLike,'likes']];const root=$('#supporterDashboard');root.replaceChildren();for(const [title,person,kind]of cells){const tile=el('div','supporter-stat '+kind);const text=el('div');text.append(el('small','',title));if(person){tile.append(avatar(person));text.append(el('strong','',person.name));const amount=el('b','',fa(person[kind]));tile.append(text,amount)}else{text.append(el('strong','','—'));tile.append(text)}root.append(tile);}}
function layoutSupporters(){const arena=$('#arena'),anchor=game.s.viewMode==='fun'?(game.s.fun.layout==='football'&&game.s.fun.football?.display!=='cards'&&$('#leagueResults')?$('#leagueResults'):$('#funCards')):$('#deck');if(!arena||!anchor?.offsetHeight)return;const a=arena.getBoundingClientRect(),r=anchor.getBoundingClientRect(),scale=a.width/arena.offsetWidth;if(!scale)return;const top=(r.bottom-a.top)/scale;if(game.s.viewMode==='fun'&&game.s.fun.layout==='football'){$('.participant-area').style.top=((r.top-a.top)/scale)+'px';$('.participant-area').style.bottom='auto';const dashboard=$('#supporterDashboard').getBoundingClientRect(),arrivalTop=(dashboard.bottom-a.top)/scale+9;$('#arrivalStack').style.top=arrivalTop+'px';$('#arrivalStack').style.bottom='auto';$('#arrivalStack').style.setProperty('--entry-rise',Math.max(50,arena.offsetHeight-arrivalTop)+'px');return;}$('#arrivalStack').style.top=(top+8)+'px';$('#arrivalStack').style.bottom='auto';$('.participant-area').style.top=(top+(experience==='portraits'?112:52))+'px';$('.participant-area').style.bottom='auto';}
const supportLayoutObserver=new ResizeObserver(()=>requestAnimationFrame(layoutSupporters));supportLayoutObserver.observe($('#deck'));supportLayoutObserver.observe($('#funCards'));addEventListener('resize',()=>requestAnimationFrame(layoutSupporters));for(const sheet of document.querySelectorAll('link[rel=stylesheet]'))sheet.addEventListener('load',()=>requestAnimationFrame(layoutSupporters));

